customMethods.script:
# Popup login: set the session identity, then close. The screen underneath is
# still mounted, and session.custom is reactive, so its operator label / mutations
# pick up the new user without any navigation or post-login re-populate.
_oldId = None
try:
	_o = self.session.custom.user
	if _o:
		_oldId = _o["appUserId"]
except Exception:
	_oldId = None
self.session.custom.user = {"appUserId": appUserId, "initials": initials, "displayName": displayName, "ignitionRole": ignitionRole}
self.session.custom.appUserId = appUserId
# audit the operator handoff (fire-and-forget; never blocks sign-in)
try:
	_t = self.session.custom.terminal
	BlueRidge.Location.AppUser.logOperatorChange(_oldId, appUserId, _t["terminalLocationId"] if _t else None)
except Exception:
	pass
system.perspective.closePopup(self.view.params.popupId or "mpp-initials")

messageHandlers.script:
a = payload.get("action") if payload else None
if a == "key":
	self.appendKey(payload.get("key"))
elif a == "backspace":
	self.backspaceKey()
elif a == "clear":
	self.clearKeys()
elif a == "enter":
	self.submitPin()

action = payload.get("action") if payload else None
self.view.custom.dialogOpen = False
if action == "registered":
	self.loginAs(payload.get("appUserId"), payload.get("initials"), payload.get("displayName"), None)
else:
	self.clearKeys()
